style.css:
@-moz-document url("https://meow.camera") {
/* Set the background image for the body */
    body {
        background-image: url("https://tr.rbxcdn.com/180DAY-58e03d9539a40de0a44015e585c4c28c/420/420/Decal/Webp/noFilter") !important;
        background-size: cover !important;   /* Make the image cover the entire page */
        background-position: center center !important; /* Center the image */
        background-attachment: fixed !important; /* Make the background fixed while scrolling */
        background-repeat: no-repeat !important; /* Prevent the image from repeating */
    }
}
